package org.viridexa.api.agent;

import java.util.*;
import java.util.regex.Pattern;
import org.springframework.stereotype.Service;
import org.viridexa.api.plant.*;
import org.viridexa.api.science.ScientificService;
import org.viridexa.api.graph.GraphService;
import org.viridexa.api.graph.GraphContract;
import static org.viridexa.api.agent.AgentContract.*;

/** Public, bounded research tools exposed to the model. */
@Service
public class ResearchTools {
 private static final Pattern SHA=Pattern.compile("[0-9a-f]{64}");
 private static final Set<String> PLANT_FIELDS=Set.of("nameZh","scientificName","nameEn","familyNameZh","genusNameLatin","morphology","distribution","recordStatus","scientificNameStatus");
 private static final Set<String> SCI_FIELDS=Set.of("id","pipeline","payload","sourceId");
 private static final Set<String> GRAPH_FIELDS=Set.of("id","nodeType","displayLabel","verificationState","publicationState","attributes","sourceReference","relationType","source","target");
 private final PlantService plants; private final ScientificService science; private final GraphService graph;
 public ResearchTools(PlantService plants, ScientificService science, GraphService graph){this.plants=plants;this.science=science;this.graph=graph;}

 /** Recheck publication at read time so a completed run does not retain withdrawn facts. */
 public boolean stillPublic(Evidence e){
  try{
   if("CATALOG".equals(e.category())){plants.getById(Long.parseLong(e.id().substring(6)));return true;}
   if(!Set.of("PUBLISHED","SOURCE_RECORD").contains(e.category()))return true;
   if(SHA.matcher(e.id()).matches())return !science.lineage(e.id()).isEmpty();
   if(e.fields().get("relationType")!=null){graph.detail(e.fields().get("source").toString());graph.detail(e.fields().get("target").toString());return true;}
   graph.detail(e.id());return true;
  }catch(RuntimeException ex){return false;}
 }
 public List<Map<String,Object>> schemas(){
  return List.of(schema("searchPlants","Search public plant records and catalog metadata",props("query",str("Plant name or term; blank returns public sources"),"limit",integer("Maximum results, 1–10")),List.of("query")),
   schema("getPlantProfile","Get a public plant profile",props("plantId",Map.of("type","integer","minimum",1,"description","Plant identifier")),List.of("plantId")),
   schema("getGraphNeighbors","Expand one hop from a public graph node",props("nodeId",str("Public graph node identifier"),"limit",integer("Maximum results, 1–10")),List.of("nodeId")),
   schema("getResearchSamples","Read public source measurement rows with confidence and independent sample identity",props("kind",str("Measurement kind"),"sampleId",Map.of("type","string","pattern","^[0-9a-f]{64}$","description","Optional SHA-256 sample identifier"),"limit",integer("Maximum results, 1–10")),List.of()),
   schema("compareOilMeasurements","Compare measurements with identical kind, basis, unit, and analyte",props("sampleIds",arrayStr("2–4 distinct SHA-256 sample identifiers"),"kind",str("Measurement kind"),"basis",str("Measurement basis"),"unit",str("Measurement unit"),"analyte",str("Optional exact analyte")),List.of("sampleIds","kind","basis","unit")),
   schema("getEvidenceLineage","Get public lineage and source documents for a graph node or published SHA-256 ID",props("recordId",str("Public graph node or published SHA-256 identifier")),List.of("recordId")));
 }
 private static Map<String,Object> schema(String name,String desc,Map<String,Object> properties,List<String> required){return Map.of("type","function","function",Map.of("name",name,"description",desc,"parameters",Map.of("type","object","properties",properties,"required",required,"additionalProperties",false)));}
 private static Map<String,Object> props(Object... kv){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<kv.length;i+=2)m.put((String)kv[i],kv[i+1]);return m;}
 private static Map<String,Object> str(String d){return Map.of("type","string","description",d,"maxLength",160);}
 private static Map<String,Object> integer(String d){return Map.of("type","integer","description",d,"minimum",1,"maximum",10);}
 private static Map<String,Object> arrayStr(String d){return Map.of("type","array","description",d,"items",Map.of("type","string","pattern","^[0-9a-f]{64}$"),"minItems",2,"maxItems",4);}

 public ToolOutput execute(String name,Map<String,Object> args){
  try { validateName(name); if(args==null) throw invalid("参数必须是对象"); return switch(name){
   case "searchPlants" -> search(args); case "getPlantProfile" -> profile(args); case "getGraphNeighbors" -> neighbors(args);
   case "getResearchSamples" -> samples(args); case "compareOilMeasurements" -> compare(args); case "getEvidenceLineage" -> lineage(args); default -> throw invalid("未知工具");
  }; } catch(Invalid e){return new ToolOutput("INVALID_ARGUMENTS",e.getMessage(),0,List.of());}
 }
 private ToolOutput search(Map<String,Object>a){only(a,"query","limit");String q=query(a);int limit=limit(a,10);var records=new ArrayList<Evidence>();
  if(!q.isBlank()){
  PlantSearchResult result=plants.search(q,limit);for(PlantRecord p:result.items()){var f=new LinkedHashMap<String,Object>();put(f,"nameZh",p.nameZh());put(f,"scientificName",p.scientificName());put(f,"nameEn",p.nameEn());put(f,"familyNameZh",p.familyNameZh());put(f,"genusNameLatin",p.genusNameLatin());put(f,"recordStatus",p.recordStatus());put(f,"scientificNameStatus",p.scientificNameStatus());records.add(ev("plant:"+p.id(),p.scientificName(),"CATALOG","SOURCE_REPORTED","METADATA_ONLY",f,List.of(),graphHref("plant:"+p.id())));}
  if(!records.isEmpty())return bounded(records,limit);
  for(ScientificService.Fact f:science.plantSearch(q,limit)){Map<String,Object> fields=whitelistPayload(f.payload());records.add(ev(f.id(),String.valueOf(fields.getOrDefault("scientific_name",fields.getOrDefault("scientificName",f.id()))),"SOURCE_RECORD",f.knowledgeConfidence(),"HUMAN_VERIFIED".equals(f.knowledgeConfidence())?"PUBLISHED":"SOURCE_PUBLIC",fields,sources(f.sourceId(),f.locator()),"/api/v1/science/lineage/"+f.id(),f.knowledgeConfidence()));}
  if(!records.isEmpty())return bounded(records,limit);
  }
  GraphContract.Page catalog=graph.search(q,limit,null);for(var node:catalog.nodes()){if(!Set.of("METADATA_ONLY","PUBLISHED","SOURCE_PUBLIC").contains(node.publicationState()))continue;Map<String,Object>fields=new LinkedHashMap<>();fields.put("nodeType",node.nodeType());fields.putAll(safe(node.attributes()));records.add(ev(node.id(),node.displayLabel(),category(node.publicationState()),node.verificationState(),node.publicationState(),fields,sourceMaps(node.sourceReference()),graphHref(node.id())));}return bounded(records,limit); }
 private ToolOutput profile(Map<String,Object>a){only(a,"plantId");long id=requiredLong(a,"plantId");PlantRecord p=plants.getById(id);Map<String,Object>f=new LinkedHashMap<>();put(f,"nameZh",p.nameZh());put(f,"scientificName",p.scientificName());put(f,"nameEn",p.nameEn());put(f,"familyNameZh",p.familyNameZh());put(f,"genusNameLatin",p.genusNameLatin());put(f,"recordStatus",p.recordStatus());put(f,"scientificNameStatus",p.scientificNameStatus());return ok(List.of(ev("plant:"+id,p.scientificName(),"CATALOG","SOURCE_REPORTED","METADATA_ONLY",f,List.of(),graphHref("plant:"+id))));}
 private ToolOutput neighbors(Map<String,Object>a){only(a,"nodeId","limit");String id=requiredString(a,"nodeId",160);int n=limit(a,10);GraphService.validateId(id);GraphContract.Page p=graph.neighbors(id,null,null,null,n,null,1);List<Evidence> out=new ArrayList<>();for(var e:p.edges()){if(!Set.of("METADATA_ONLY","PUBLISHED","SOURCE_PUBLIC").contains(e.publicationState()))continue;Map<String,Object>f=new LinkedHashMap<>();f.put("relationType",e.relationType());f.put("source",e.source());f.put("target",e.target());put(f,"displayLabel",e.displayLabel());out.add(ev(e.id(),e.displayLabel(),category(e.publicationState()),e.verificationState(),e.publicationState(),f,sourceMaps(e.sourceReference()),graphHref(id)));}return bounded(out,n);}
 private ToolOutput samples(Map<String,Object>a){only(a,"kind","sampleId","limit");String id=a.containsKey("sampleId")?requiredString(a,"sampleId",64):null;if(id!=null)sha(id);String kind=optionalString(a,"kind",64);int n=limit(a,10);var rows=science.measurements(kind,id,null,null,n);return sampleOutput(rows);}
 private ToolOutput compare(Map<String,Object>a){only(a,"sampleIds","kind","basis","unit","analyte");Object x=a.get("sampleIds");if(!(x instanceof List<?> ids)||ids.size()<2||ids.size()>4)throw invalid("sampleIds 必须包含2–4项");Set<String> distinct=new LinkedHashSet<>();for(Object v:ids){if(!(v instanceof String s))throw invalid("sampleIds 必须是字符串");sha(s);distinct.add(s);}if(distinct.size()!=ids.size())throw invalid("sampleIds 必须互不相同");String kind=requiredString(a,"kind",64);if(!Set.of("OIL_CONTENT","OIL_FA_COMPOSITION","FAME_COMPOSITION").contains(kind))throw invalid("仅比较植物油测量，食品营养数据不适用");String basis=requiredString(a,"basis",64),unit=requiredString(a,"unit",64),analyte=optionalString(a,"analyte",100);if(!"%".equals(unit))return new ToolOutput("NOT_COMPARABLE","植物油百分比的单位不适用",0,List.of());if(basis.toLowerCase(Locale.ROOT).matches(".*(as.reported|unknown|unspecified|未知|不明|未说明).*"))return new ToolOutput("NOT_COMPARABLE","来源计量基础仍不明确，不能据同名字段判定可比",0,List.of());List<ScientificService.SampleComparison> all=new ArrayList<>();Set<String> covered=new HashSet<>(),analytes=new HashSet<>();boolean incompatible=false;for(String id:distinct){var rows=science.measurements(kind,id,basis,null,10);for(var r:rows){if(!Objects.equals(r.measurementKind(),kind)||!Objects.equals(r.basis(),basis)){incompatible=true;continue;}if(!Objects.equals(r.unit(),unit)||r.numericValue()==null){incompatible=true;continue;}if(analyte!=null&&!Objects.equals(r.analyte(),analyte)){incompatible=true;continue;}covered.add(id);analytes.add(r.analyte()==null?"":r.analyte());all.add(r);}}if(incompatible||covered.size()!=distinct.size()||all.size()<2||(analyte==null&&analytes.size()!=1)){all.clear();return new ToolOutput("NOT_COMPARABLE","样本缺少同口径、非空数值，或测量单位/分析物不一致",0,List.of());}return new ToolOutput("SIDE_BY_SIDE","计量字段一致，但物种身份、部位和实验方法尚未核对；仅并列展示来源记录，不计算差异或合成组分。",all.size(),sampleEvidence(all));}
 private ToolOutput sampleOutput(List<ScientificService.SampleComparison> rows){return ok(sampleEvidence(rows));}
 private List<Evidence> sampleEvidence(List<ScientificService.SampleComparison> rows){List<Evidence> out=new ArrayList<>();for(var r:rows){Map<String,Object>f=new LinkedHashMap<>();put(f,"sampleId",r.sampleId());put(f,"studyId",r.studyId());f.put("identityState","UNLINKED");f.put("associationNotice","独立样本尚未关联植物，不能视为当前所选植物的测量。");put(f,"kind",r.measurementKind());put(f,"analyte",r.analyte());put(f,"value",r.rawValue()==null?r.numericValue():r.rawValue());put(f,"unit",r.unit());put(f,"basis",r.basis());out.add(ev(r.evidenceId(),r.analyte(),"SOURCE_RECORD",r.knowledgeConfidence(),"HUMAN_VERIFIED".equals(r.knowledgeConfidence())?"PUBLISHED":"SOURCE_PUBLIC",f,sources(r.sourceId(),null),"/api/v1/science/lineage/"+r.evidenceId(),r.knowledgeConfidence()));}return out;}
 private ToolOutput lineage(Map<String,Object>a){only(a,"recordId");String id=requiredString(a,"recordId",160);List<Evidence> out=new ArrayList<>();if(SHA.matcher(id).matches()){var rows=new ArrayList<Map<String,Object>>(science.lineage(id));rows.addAll(science.documents(id));for(var r:rows){Map<String,Object>f=safe(r);String confidence=Objects.toString(f.get("knowledge_confidence"),"SOURCE_REPORTED");String pub="HUMAN_VERIFIED".equals(confidence)?"PUBLISHED":"SOURCE_PUBLIC";String rid=Objects.toString(f.getOrDefault("id",id));out.add(ev(rid,Objects.toString(f.getOrDefault("label",f.getOrDefault("displayLabel",rid))),"SOURCE_RECORD",confidence,pub,f,List.of(),"/api/v1/science/lineage/"+id,confidence));}}else{GraphService.validateId(id);var node=graph.detail(id);if(Set.of("METADATA_ONLY","PUBLISHED","SOURCE_PUBLIC").contains(node.publicationState())){Map<String,Object>f=safe(node.attributes());f.put("nodeType",node.nodeType());out.add(ev(node.id(),node.displayLabel(),category(node.publicationState()),node.verificationState(),node.publicationState(),f,sourceMaps(node.sourceReference()),graphHref(id)));}var p=graph.neighbors(id,null,null,null,10,null,1);for(var e:p.edges()){if(!Set.of("METADATA_ONLY","PUBLISHED","SOURCE_PUBLIC").contains(e.publicationState()))continue;Map<String,Object>f=new LinkedHashMap<>();f.put("relationType",e.relationType());f.put("source",e.source());f.put("target",e.target());out.add(ev(e.id(),e.displayLabel(),category(e.publicationState()),e.verificationState(),e.publicationState(),f,sourceMaps(e.sourceReference()),graphHref(id)));}}return bounded(out,10);}
 private static Evidence ev(String id,String label,String category,String verification,String publication,Map<String,Object> fields,List<Map<String,Object>> sources,String href){return ev(id,label,category,verification,publication,fields,sources,href,null);}
 private static Evidence ev(String id,String label,String category,String verification,String publication,Map<String,Object> fields,List<Map<String,Object>> sources,String href,String confidence){return new Evidence(id,label==null?id:label,category,verification,publication,fields,sources,href,href!=null&&href.startsWith("/api/v1/graph/nodes/")?href.substring("/api/v1/graph/nodes/".length()):null,confidence);}
 private static ToolOutput ok(List<Evidence> records){return records.isEmpty()?new ToolOutput("INSUFFICIENT_EVIDENCE","没有找到公开证据",0,List.of()):new ToolOutput("SUCCESS","找到公开证据",records.size(),records);}
 private static ToolOutput bounded(List<Evidence> records,int limit){Map<String,Evidence>unique=new LinkedHashMap<>();for(Evidence e:records)unique.putIfAbsent(e.id(),e);var out=unique.values().stream().limit(limit).toList();return ok(out);}
 private static String category(String p){return "PUBLISHED".equals(p)?"PUBLISHED":"SOURCE_PUBLIC".equals(p)?"SOURCE_RECORD":"METADATA";}
 private static List<Map<String,Object>> sources(String id,Object locator){if(id==null)return List.of();Map<String,Object>m=new LinkedHashMap<>();m.put("sourceId",id);if(locator instanceof Map<?,?> lm)for(String k:List.of("page","pdf_page","printed_page","table","sheet","row","column","archive_member","record_ordinal","field")){Object v=lm.get(k);if(v instanceof String||v instanceof Number)m.put(k,v);}return List.of(m);}
 private static List<Map<String,Object>> sourceMaps(List<GraphContract.SourceReference> refs){List<Map<String,Object>>out=new ArrayList<>();for(var r:refs){Map<String,Object>m=new LinkedHashMap<>();put(m,"sourceId",r.sourceId());put(m,"label",r.displayLabel());put(m,"sha256",r.sha256());put(m,"version",r.version());put(m,"licenseState",r.licenseState());if(r.locator() instanceof Map<?,?> loc)for(String k:List.of("page","pdf_page","printed_page","table","sheet","row","column","archive_member","record_ordinal","field")){Object v=loc.get(k);if(v instanceof String||v instanceof Number)m.put(k,v);}out.add(m);}return out;}
 private static String graphHref(String id){return "/api/v1/graph/nodes/"+id;}
 private static String query(Map<String,Object>a){Object v=a.get("query");if(v==null)return "";if(!(v instanceof String s)||s.length()>160)throw invalid("参数格式无效");return s.trim();}
 private static Map<String,Object> whitelistPayload(Object payload){if(!(payload instanceof Map<?,?> input))return Map.of();Set<String> allowed=Set.of("scientific_name","accepted_name","synonym_name","name_zh","scientificName","name","nameZh","nameEn","family","genus","pipeline","measurementKind","sampleId","analyte","value","unit","basis","traits","normalized_traits");Map<String,Object>out=new LinkedHashMap<>();for(String k:allowed)if(input.containsKey(k))out.put(k,input.get(k));return out;}
 private static Map<String,Object> safe(Map<String,Object> input){Set<String> allowed=Set.of("id","label","displayLabel","nodeType","verificationState","publicationState","relationType","source","target","pipeline","kind","analyte","sampleId","studyId","value","unit","basis","sha256","licenseState","version","source_id","content_sha256","sourceId","evidenceId","dataset","source_document","version_label","license_state","integrity_state","action","decided_at","decision_id","locator");Map<String,Object>out=new LinkedHashMap<>();for(String k:allowed){Object v=input.get(k);if((v instanceof String||v instanceof Number||v instanceof Boolean)&&!sensitivePath(v.toString()))out.put(k,v);else if(k.equals("locator")&&v instanceof Map<?,?> loc){Map<String,Object> clean=new LinkedHashMap<>();for(String lk:List.of("pdf_page","printed_page","table","row","record_ordinal","record_id","archive_member","field")){Object lv=loc.get(lk);if(lv instanceof String||lv instanceof Number)clean.put(lk,lv);}out.put(k,clean);}}return out;}
 private static boolean sensitivePath(String s){return s.contains("/Users/")||s.contains("/home/")||s.startsWith("/app/")||s.matches("^[A-Za-z]:.*");}
 private static void put(Map<String,Object>m,String k,Object v){if(v!=null)m.put(k,v);}
 private static void validateName(String n){if(!Set.of("searchPlants","getPlantProfile","getGraphNeighbors","getResearchSamples","compareOilMeasurements","getEvidenceLineage").contains(n))throw invalid("未知工具");}
 private static void only(Map<String,Object>a,String... allowed){Set<String>s=Set.of(allowed);for(String k:a.keySet())if(!s.contains(k))throw invalid("包含不允许的参数");}
 private static String requiredString(Map<String,Object>a,String k,int max){Object v=a.get(k);if(!(v instanceof String s)||s.isBlank()||s.length()>max)throw invalid("参数格式无效");return s.trim();}
 private static String optionalString(Map<String,Object>a,String k,int max){return !a.containsKey(k)||a.get(k)==null?null:requiredString(a,k,max);}
 private static long requiredLong(Map<String,Object>a,String k){Object v=a.get(k);if(!(v instanceof Number n)||n.longValue()<1||n.doubleValue()!=n.longValue())throw invalid("参数无效: "+k);return n.longValue();}
 private static int limit(Map<String,Object>a,int d){if(!a.containsKey("limit"))return d;Object v=a.get("limit");if(!(v instanceof Number n)||n.doubleValue()!=n.intValue()||n.intValue()<1||n.intValue()>10)throw invalid("limit必须为1–10");return n.intValue();}
 private static void sha(String s){if(!SHA.matcher(s).matches())throw invalid("SHA-256标识无效");}
 private static Invalid invalid(String s){return new Invalid(s);} private static final class Invalid extends RuntimeException{Invalid(String s){super(s);}}
}
